"use strict";const utils=require("../utils");module.exports=function(defaultFuncs,api,ctx){return async function markAsReadAll(){const form={folder:"inbox"};try{const parsedData=await defaultFuncs.post("https://www.facebook.com/ajax/mercury/mark_folder_as_read.php",ctx.jar,form).then(utils.parseAndCheckLogin(ctx,defaultFuncs));if(parsedData.error){throw parsedData}return}catch(err){utils.error("markAsReadAll",err);throw err}}};
